using System;
using UnityEngine;

namespace Soup.Runtime.Blackboards
{
    /// <summary>
    /// Base class for blackboard variables. 
    /// </summary>
    [Serializable]
    public abstract class ABlackboardVariable
    {
        /** Generated by the editor when the variable is added. */
        [SerializeField, HideInInspector]
        private string m_id;
        public string Id => m_id;

        [SerializeField]
        private string m_name;
        public string Name => m_name;
        
        public abstract Type ValueType { get; }

        private protected ABlackboardVariable() { }

        /** For editor use. */
#if UNITY_EDITOR
        internal void SetId(string id)
        {
            m_id = id;
        }

        internal void SetName(string name)
        {
            m_name = name;
        }

        internal const string ID_FIELD_NAME = nameof(m_id);
        internal const string NAME_FIELD_NAME = nameof(m_name);
        internal const string VALUE_FIELD_NAME = "m_value"; // Declared by ABlackboardVariable<T>.
#endif
    }

    [Serializable]
    public abstract class ABlackboardVariable<T> : ABlackboardVariable
    {
        [SerializeField]
        private T m_value;
        public T Value
        {
            get => m_value;
            set => m_value = value;
        }

        public sealed override Type ValueType => typeof(T);
    }
}
